parameters.jsCode:
const ev = $input.first().json.output ?? $input.first().json;
const app = $('Prepare Application').first().json;
const profile = $('Extract Candidate Profile').first().json.output || {};

const cv = String(app.cvtext || '').toLowerCase();
const problems = [];

// Normalize text
function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[-_/]/g, ' ')
    .replace(/[^\w\s+#.]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const normalizedCV = normalize(cv);

// Equivalent skill names
const skillAliases = {
  'error handling': [
    'error handling',
    'error management',
    'exception handling',
    'try catch',
    'debugging'
  ],

  'document loaders': [
    'document loaders',
    'document loader',
    'default data loader',
    'pdf loader',
    'data loader'
  ],

  'python fundamentals': [
    'python fundamentals',
    'python basics',
    'basic python',
    'python programming'
  ],

  'webhooks': [
    'webhooks',
    'webhook',
    'http trigger'
  ],

  'api integration': [
    'api integration',
    'api integrations',
    'rest api',
    'http request'
  ],

  'vector stores': [
    'vector stores',
    'vector store',
    'vector database'
  ],

  'rag': [
    'rag',
    'retrieval augmented generation',
    'retrieval augmented'
  ]
};

// Verify skill using equivalent terms
function isSkillVerified(skill) {
  const name = normalize(skill).split(' (')[0];

  if (!name) return false;

  const aliases = skillAliases[name] || [name];

  return aliases.some(alias =>
    normalizedCV.includes(normalize(alias))
  );
}

// Validate score
if (
  !Number.isInteger(ev.score) ||
  ev.score < 0 ||
  ev.score > 100
) {
  problems.push('score must be a whole number from 0 to 100');
}

// Validate recommendation
if (!['interview', 'maybe', 'reject'].includes(ev.recommendation)) {
  problems.push('recommendation must be interview, maybe or reject');
}

// Recommendation rules
if (ev.recommendation === 'interview' && ev.score < 70) {
  problems.push('interview needs a score of 70 or more');
}

if (ev.recommendation === 'reject' && ev.score >= 40) {
  problems.push('reject needs a score below 40');
}

// NEW: Validate maybe score range
if (ev.recommendation === 'maybe' &&
    (ev.score < 40 || ev.score >= 70)) {
  problems.push('maybe needs a score between 40 and 69');
}

// Validate requirements
if (
  !(ev.matched_requirements || []).length &&
  !(ev.missing_requirements || []).length
) {
  problems.push('the evaluation lists no requirements');
}

// Verify extracted skills
const skills = Array.isArray(profile.skills)
  ? profile.skills
  : [];

const unverified = skills.filter(
  skill => !isSkillVerified(skill)
);

// Only flag if more than 2 skills remain unverified
if (unverified.length > 2) {
  problems.push(
    'skills not found in the CV: ' + unverified.join(', ')
  );
}

// Preserve applicant information
const { cvtext, jobRequirements, ...applicant } = app;

return [{
  json: {
    ...applicant,
    ...ev,

    yearsExperience: profile.years_experience ?? '',

    topSkills: skills.slice(0, 6).join(', '),

    valid: problems.length === 0,

    problems: problems.join('; '),

    unverifiedSkills: unverified
  }
}];
